import json
# The dotnet package list --format json with solution can produce concatenated JSON objects
# Parse both files and compare
def parse_packages(f):
    data = json.load(open(f))
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw['topLevelPackages']:
                result[(name, pkg['id'])] = pkg['resolvedVersion']
    return result

b = parse_packages('baseline-packages.json')
a = parse_packages('after-cpm-packages.json')

if b == a:
    print('MATCH: All packages resolve to identical versions')
else:
    print('DIFFERENCES:')
    for k in sorted(set(list(b.keys()) + list(a.keys()))):
        bv = b.get(k, 'MISSING')
        av = a.get(k, 'MISSING')
        if bv != av:
            print(f'  {k}: {bv} -> {av}')
"

